import java.util.List;
import java.util.ArrayList;
import java.util.Iterator;

/**
 * Write a description of class Disease here.
 *
 * @version (a version number or a date)
 */
public class Disease
{

    // The possibility that an animal may be infected by a disease.
    public static final double INFECTION_RATE = 0.3;
    // The possibility an animal may die of a disease.
    public static final double MORTALITY_RATE = 0.05;
    // The steps an animal need to withstand in order to get immunity
    public static final int NUMBER_OF_STEP_TO_WITHSTAND = 3;
    // The probability that the disease may occur
    private static final double DISEASE_OCCURENCE_PROBABILITY = 0.2;

    // Identify if a disease start to spread
    private boolean isSpread;

    public Disease()
    {
         isSpread = false;
    }


    public boolean getIsSpread(){
        return isSpread;
    }

    public void setIsSpread(boolean bl){
        isSpread = bl;
    }

    /**
     * create the source of infection
     */
    protected void creationSourceOfInfection(List<Creature> creatures, int step){

        if(!getIsSpread() && Randomizer.getRandom().nextDouble() <= DISEASE_OCCURENCE_PROBABILITY){
            ArrayList<Animal> animalCollection = new ArrayList<>();
            Iterator<Creature> it = creatures.iterator();
            while(it.hasNext()){
                Creature creature = it.next();
                if(creature instanceof Animal){
                    Animal animal = (Animal)creature;
                        animalCollection.add(animal);
                }
            }

            for(Animal ani: animalCollection){
                if(Randomizer.getRandom().nextDouble() <= 0.3){
                    ani.setIsInfected(true);
                    ani.infectionStartStep = step;
                    setIsSpread(true);

                }
            }


        }

    }





}

/**
 * A simple model of a Salmon.
 * 
 * Salmons age, move, eat seaweed, consume oxygen, propogate,
 * and may get infected by disease and die of that or of weather.
 *
 * @version 2022/03/02
 */
public class Salmon extends Animal
{
    // Characteristics shared by all salmons (class variables).

    // The age at which a salmon can start to breed.
    private static final int BREEDING_AGE = 4;
    // The age to which a salmon can live.
    private static final int MAX_AGE = 50;
    // The likelihood of a salmon breeding.
    private static final double BREEDING_PROBABILITY = 0.3;
    // The maximum number of births.
    private static final int MAX_LITTER_SIZE = 15;

    // The food value of a single salmon. In effect, this is the
    // number of steps a fox can go before it has to eat again.
    private static final int SEAWEED_FOOD_VALUE = 13;

    /**
     * Create a new salmon. A salmon may be created with age
     * zero (a new born) or with a random age.
     * 
     * @param randomAge If true, the salmon will have a random age.
     * @param field The field currently occupied.
     * @param location The location within the field.
     */
    public Salmon(boolean randomAge, Field field, Location location)
    {
        super(randomAge, field, location, MAX_AGE, SEAWEED_FOOD_VALUE);
    }


    /**
     * Decide if two salmons countered has different sex;
     */
    public boolean encounterWithDiffSex(){
        return encounterWithDiffSex(Salmon.class, 2);
    }

    protected int getBreedingAge(){
        return BREEDING_AGE;
    }

    protected double getBreedingProbability(){
        return BREEDING_PROBABILITY;
    }

    protected int getMaxLitterSize(){
        return MAX_LITTER_SIZE;
    }

    protected boolean requiresDifferentSexToBreed(){
        return true;
    }

    protected Animal createYoung(Field field, Location location){
        return new Salmon(false, field, location);
    }

    protected int getFoodValue(Object creature){
        if(creature instanceof Seaweed)
            return SEAWEED_FOOD_VALUE;
        return 0;
    }

}
