 52	    public Animal(boolean randomAge, Field field, Location location, int maxAge, int foodValue,
 53	                  int breedingAge, double breedingProbability, int maxLitterSize,
 54	                  boolean requiresDifferentSexToBreed){
 55	        super(field, location);
 56	        sex = (int)(Math.round(Math.random()));
 57	        this.maxAge = maxAge;
