 60	        this.maxLitterSize = maxLitterSize;
 61	        this.requiresDifferentSexToBreed = requiresDifferentSexToBreed;
 62	        if(randomAge) {
 63	            age = rand.nextInt(maxAge);
 64	            foodLevel = rand.nextInt(foodValue);
 65	        }
 66	        else {
 67	            age = 0;
 68	            foodLevel = foodValue;
