 77	    /**
 78	     * This is what animals do most of the time: age, get hungry, breed,
 79	     * search for food, move and consume oxygen.
 80	     *
 81	     * @param newAnimals A list to return newly born animals.
 82	     * @param atDayTime true if current step is daytime false otherwise.
 83	     * @param oxygenLevel The inital level of dissolved oxygen in the water.
 84	     * @param disease The disease may happened during simulation.
 85	     * @param step current step.
 86	     *
 87	     * @return the oxygen level the animal consumed after action.
 88	     */
 89	    public double act(List<Creature> newAnimals, boolean atDayTime, double oxygenLevel, Disease disease, int step)
 90	    {
 91	        if(oxygenLevel < ANIMAL_OXYGEN_REQUIRED){
 92	            setDead();
 93	            return 0;
 94	        }
 95	
 96	        // If the animal dies of disease, it will consume no oxygen.
 97	        if(dieOfInfection(disease))
 98	            return 0;
 99	
100	        // Check if the animal is qualified for immunity.
101	        ifCanGrantImmunity(disease, step);
102	
103	        incrementAge();
104	        incrementHunger();
105	
106	        if(isAlive() && !needSleep(atDayTime)) {
107	            giveBirth(newAnimals);
108	
109	            Location newLocation = search(disease, step);
110	            if(newLocation == null) {
111	                // No food found - try to move to a free location.
112	                newLocation = getField().freeAdjacentLocation(getLocation());
113	            }
114	            // See if it was possible to move.
115	            if(newLocation != null) {
116	                setLocation(newLocation);
117	            }
118	            else {
119	                // Overcrowding.
120	                setDead();
121	            }
122	
123	        }
124	
125	        return -ANIMAL_OXYGEN_REQUIRED;
126	    }
