128	    /**
129	     * Increase the age. This could result in the animal's death.
130	     */
131	    private void incrementAge()
132	    {
133	        age++;
134	        if(age > maxAge) {
135	            setDead();
136	        }
137	    }
138	
139	    /**
140	     * Make this animal more hungry. This could result in the animal's death.
141	     */
142	    private void incrementHunger()
143	    {
144	        foodLevel--;
145	        if(foodLevel <= 0) {
146	            setDead();
147	        }
148	    }
149	
150	    /**
151	     * Check whether or not this animal is to give birth at this step.
152	     * New births will be made into free adjacent locations.
153	     * @param newAnimals A list to return newly born animals.
154	     */
155	    private void giveBirth(List<Creature> newAnimals)
156	    {
157	        Field field = getField();
158	        List<Location> free = field.getFreeAdjacentLocations(getLocation());
159	        int births = breed();
160	        for(int b = 0; b < births && free.size() > 0; b++) {
161	            Location loc = free.remove(0);
162	            Animal young = createYoung(field, loc);
163	            newAnimals.add(young);
164	        }
165	    }
