167	    /**
168	     * Generate a number representing the number of births,
169	     * if it can breed.
170	     * @return The number of births (may be zero).
171	     */
172	    private int breed()
173	    {
174	        int births = 0;
175	        if(canBreed() && rand.nextDouble() <= breedingProbability) {
176	            births = rand.nextInt(maxLitterSize) + 1;
177	        }
178	        return births;
179	    }
180	
181	    /**
182	     * Check if this animal can breed.
183	     * @return true if this animal can breed, false otherwise.
184	     */
185	    private boolean canBreed()
186	    {
187	        return age >= breedingAge && (!requiresDifferentSexToBreed || encounterWithDiffSex());
188	    }
