190	    /**
191	     * Look for food adjacent to the current location.
192	     * Only the first live food source is eaten. If a nearby animal is
193	     * infected, then this animal also may be infected.
194	     * @param disease disease.
195	     * @param step int current step.
196	     * @return Where food was found, or null if it wasn't.
197	     */
198	    public Location search(Disease disease, int step)
199	    {
200	        Field field = getField();
201	        List<Location> adjacent = field.adjacentLocations(getLocation(), 1);
202	        for(Location loc: adjacent) {
203	            Object creature = field.getObjectAt(loc);
204	            if(creature instanceof Animal) {
205	                Animal animal = (Animal) creature;
206	                if(animal.getIsInfected()) {
207	                    makeInfected(disease, step);
208	                }
209	            }
210	
211	            int foodValue = getFoodValue(creature);
212	            if(foodValue > 0 && creature instanceof Creature) {
213	                Creature food = (Creature) creature;
214	                if(food.isAlive()) {
215	                    food.setDead();
216	                    foodLevel = foodValue;
217	                    return loc;
218	                }
219	            }
220	        }
221	        return null;
222	    }
