238	    /**
239	     * Look for a nearby animal of the given class with a different sex.
240	     * @param animalClass The class of animal to find.
241	     * @param adjacentDistance Controls the search range.
242	     * @return true if a matching nearby animal has a different sex.
243	     */
244	    protected boolean encounterWithDiffSex(Class<? extends Animal> animalClass, int adjacentDistance)
245	    {
246	        Field field = getField();
247	        List<Location> adjacent = field.adjacentLocations(getLocation(), adjacentDistance);
248	        for(Location where: adjacent) {
249	            Object animalAtThisLoc = field.getObjectAt(where);
250	            if(animalClass.isInstance(animalAtThisLoc)) {
251	                Animal animal = (Animal) animalAtThisLoc;
252	                if(this.getSex() != animal.getSex())
253	                    return true;
254	            }
255	        }
256	        return false;
257	    }
